'use strict';
const $ = s => document.querySelector(s);
const state = {view:'notch',notch:'idle',tab:'conversation',category:'General',width:'wide',theme:'dark',display:'notched',draft:'Hi Maya,\n\nThursday at 2 works well for me. I’ll bring the updated outline.\n\nThanks,\nAlex',prompt:'',search:'launch timeline',selection:0,sidebar:true,readingLarge:false,preferences:{'Open on login':true,'Expand on hover':true},showSources:false,hideSources:false};
const icons = {window:'<rect x="2" y="3" width="16" height="14" rx="2"/><path d="M11 2h7v7M18 2l-9 9"/>',close:'<path d="m5 5 10 10M15 5 5 15"/>',search:'<circle cx="8" cy="8" r="5.5"/><path d="m12 12 5 5"/>',sidebar:'<rect x="2" y="3" width="16" height="14" rx="2"/><path d="M7 3v14"/>',chat:'<path d="M3 3h14v11H8l-5 3Z"/>',research:'<circle cx="10" cy="10" r="8"/><path d="M2 10h16M10 2c-5 4-5 12 0 16M10 2c5 4 5 12 0 16"/>',memory:'<path d="M5 3h10v15l-5-4-5 4Z"/>',settings:'<circle cx="10" cy="10" r="3"/><path d="M10 1v3m0 12v3M1 10h3m12 0h3M4 4l2 2m8 8 2 2M4 16l2-2m8-8 2-2"/>',send:'<path d="M10 17V3M4 9l6-6 6 6"/>',check:'<path d="m3 10 4 4L17 4"/>',stop:'<rect x="5" y="5" width="10" height="10" rx="1"/>',file:'<path d="M4 2h8l4 4v12H4ZM12 2v5h4M7 11h6M7 14h6"/>',plus:'<path d="M10 3v14M3 10h14"/>'};
const icon = name => `<svg class="glyph" viewBox="0 0 20 20" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,cls='',symbol='')=>`<button class="${cls}" data-action="${action}">${symbol?icon(symbol):''}${label}</button>`;
const announce=t=>{$('#announcement').textContent=t;};
const brand=()=>'<span class="brand"><span class="orb" aria-hidden="true"></span>Wisp</span>';
function composer(placeholder='Ask anything. Stay in your flow.'){return `<div class="composer"><label class="sr-only" for="prompt">Message Wisp</label><textarea id="prompt" placeholder="${placeholder}">${esc(state.prompt)}</textarea><div class="composer-footer"><span>↵ Send &nbsp; · &nbsp; ⇧↵ New line</span>${btn('<span class="sr-only">Send sample request</span>','send','primary icon','send')}</div></div>`;}
function notch(){
 const header=`<div class="surface-header">${brand()}<div class="row">${btn('Open window','open-window','small','window')}${btn('<span class="sr-only">Hide Wisp</span>','hide','icon','close')}</div></div>`;
 let body='';
 if(state.notch==='idle') body=`<h1>A little help, right here.</h1><p class="muted">Ask a question. Find a detail. Make room for your day.</p>${composer()}<div class="suggestions">${btn('What’s ahead today?','sample-day')}${btn('Find a detail in this document','open-search')}</div><div class="notch-footer"><span>Ready on this Mac</span><span>⌥Space to return</span></div>`;
 if(state.notch==='processing') body=`<div class="request">${esc(state.prompt||'Find Maya’s latest email and draft a reply for Thursday.')}</div><div class="progress-heading"><span class="spinner" aria-hidden="true"></span><span role="status">Preparing a reply</span></div><p class="muted small">Checking the thread before writing.</p><div class="steps"><div class="step">${icon('check')}<span>Found the conversation with Maya</span></div><div class="step">${icon('check')}<span>Checked Thursday’s availability</span></div><div class="step"><span class="count">3</span><span>Drafting a reply for your review</span></div></div><div class="row between"><span class="muted small">You’ll review the email before it’s sent.</span>${btn('Stop','stop','secondary','stop')}</div>`;
 if(state.notch==='approval') body=`<span class="eyebrow">Needs your approval</span><h1 style="margin-top:10px">Review before sending.</h1><p class="muted small">One email, from your Work account. Nothing sent yet.</p><div class="draft"><dl><dt>From</dt><dd>Alex · alex@example.com</dd><dt>To</dt><dd>Maya Chen · maya@example.com</dd><dt>Subject</dt><dd>Re: Thursday planning session</dd><dt>Files</dt><dd>No attachments</dd></dl><hr class="rule"><label class="sr-only" for="draft">Email draft, editable</label><textarea id="draft">${esc(state.draft)}</textarea></div><div class="decision">${btn('Not now','defer','secondary')}${btn('Send this email','approve','primary')}</div><div class="notch-footer"><span>Applies to this email only</span><span>Esc · Not now</span></div>`;
 if(['approved','canceled'].includes(state.notch)) body=`<div class="progress-heading">${icon('check')}${state.notch==='approved'?'Sample approval recorded':'Request stopped'}</div><p class="muted">${state.notch==='approved'?'This is a prototype. No email was sent.':'Your request is preserved. You can edit it and try again.'}</p>${composer('Continue the conversation…')}`;
 if(['hidden','deferred'].includes(state.notch)) return `<div class="collapsed">${brand()}<p class="small">${state.notch==='deferred'?'Email approval is still pending.':'Ready when you are.'}</p>${btn(state.notch==='deferred'?'Review pending email':'Show Wisp',state.notch==='deferred'?'resume':'show','secondary')}</div>`;
 return `<section class="notch" aria-label="Expanded Wisp command panel">${header}${body}</section>`;
}
function sidebar(){return `<nav class="sidebar" aria-label="Workspace navigation">${btn('New conversation','new','secondary','plus')}<div class="eyebrow">Workspace</div>${['conversation','research','memory'].map((t,i)=>`<button data-tab="${t}" aria-pressed="${state.tab===t}">${icon(['chat','research','memory'][i])}${['Conversations','Research','Memory'][i]}</button>`).join('')}<div class="eyebrow">Recent conversations</div><button data-tab="conversation">A calmer Thursday</button><button data-tab="research">A launch worth remembering</button><div class="sidebar-bottom"><div class="small muted">${brand()}<br>On this Mac</div>${btn('Settings','open-settings','','settings')}</div></nav>`;}
function titlebar(title,extras=''){return `<div class="titlebar"><div class="traffic" aria-label="Native window controls depicted; decorative prototype"><span></span><span></span><span></span></div>${btn('<span class="sr-only">Toggle sidebar</span>','sidebar','icon','sidebar')}<span class="toolbar-label">${title}</span><span class="spacer"></span>${extras}${btn('<span class="sr-only">Return to notch</span>','return-notch','icon','window')}</div>`;}
function conversation(){return `<div class="content-inner conversation-content"><div class="conversation-scroll"><span class="eyebrow">Thursday, September 10</span><h1>A calmer Thursday.</h1><div class="user-message">What does tomorrow look like? Leave me a little room to prepare for Maya’s meeting.</div><article class="answer body-copy"><div class="answer-title">${brand()}</div><p>You have two meetings tomorrow, with a clear stretch in between.</p><div class="agenda"><div class="agenda-row"><time>10:00</time><div><b>Team check-in</b><div class="muted small">30 minutes · Work calendar</div></div></div><div class="agenda-row"><time>11:00</time><div><b>Time to prepare</b><div class="muted small">Suggested · 45 minutes, not yet scheduled</div></div></div><div class="agenda-row"><time>14:00</time><div><b>Planning with Maya</b><div class="muted small">45 minutes · Work calendar</div></div></div></div><p>I’d use the late morning to review the outline. Maya’s latest note asks for a simpler first release. <span class="citation">1</span></p></article>${btn('Review email draft','review','secondary')} ${btn('View source','show-source','small')}</div>${composer('Ask a follow-up…')}</div>`;}
function research(){return `<div class="content-inner"><span class="eyebrow">Research / saved report</span><h1>A launch worth remembering.</h1><p class="muted small">A focused plan for a small product team · Sample report</p><div class="report-meta"><span class="pill">${icon('check')} Research complete</span><span class="pill">2 sample sources</span></div><article class="body-copy"><h2>Start with one useful promise.</h2><p>The strongest first release gives people a clear reason to return. Make the core task feel complete before expanding the feature list. <span class="citation">1</span></p><div class="report-callout">For this team, prioritize a dependable daily workflow, an understandable first run, and a direct path to feedback.</div><h2>What to do next</h2><p><b>1. Make the first minute count.</b><br>Show the core action with a realistic example. Let people try it before asking them to configure everything.</p><p><b>2. Keep the release narrow.</b><br>Choose one outcome to evaluate in the first week. <span class="citation">2</span></p><h2>Where the evidence is thin</h2><p>No usage data is included in this fixture. Validate these ideas with the team’s actual users.</p></article></div>`;}
function memory(){return `<div class="content-inner"><span class="eyebrow">Memory</span><h1>Useful things, remembered.</h1><p class="muted">Review what Wisp remembers and where it came from.</p><div class="row" style="margin:24px 0 7px"><span class="pill">Saved · 3</span><span class="muted small">Synthetic examples</span></div>${[['Work preferences','Keep meeting summaries brief.','You asked Wisp to remember this · Sep 3'],['Writing style','Use a warm, direct tone in email drafts.','Saved from conversation · Sep 5'],['Current project','The first release should focus on one daily workflow.','Launch planning notes · Sep 8']].map((x,i)=>`<article class="memory-row"><div class="memory-mark">${icon('memory')}</div><div class="spacer"><b>${x[0]}</b><p>${x[1]}</p><span class="small muted">${x[2]}</span></div>${btn('Review',`memory-${i}`,'small secondary')}</article>`).join('')}<p class="muted small" style="margin-top:22px">Corrections belong beside the memory, with its source visible.</p></div>`;}
function inspector(){return `<aside class="inspector" aria-label="Source evidence"><div class="row between"><h3>Sources</h3>${btn('<span class="sr-only">Close sources</span>','hide-source','icon','close')}</div><div class="source"><span class="eyebrow">01 · ${state.tab==='research'?'TEAM NOTES':'MAIL'}</span><b>${state.tab==='research'?'First-release principles':'Thursday planning session'}</b><span class="muted">${state.tab==='research'?'Product team · Sep 4':'Maya Chen · Yesterday'}</span><q>${state.tab==='research'?'Make one workflow feel complete.':'Let’s keep the first release simple and leave room for feedback.'}</q></div><div class="source"><span class="eyebrow">02 · ${state.tab==='research'?'PLANNING':'CALENDAR'}</span><b>${state.tab==='research'?'Launch outline':'Work calendar'}</b><span class="muted">${state.tab==='research'?'Updated Sep 8':'Thursday, Sep 10'}</span></div><p class="muted small">Illustrative evidence.<br>All content is fictional.</p></aside>`;}
function workspace(){return `<section class="window ${state.showSources?'show-sources':''} ${state.hideSources?'sources-hidden':''} ${state.width==='narrow'?'narrow':''} ${state.sidebar?'':'hidden-sidebar'}" aria-label="Wisp standard window">${titlebar(state.tab==='conversation'?'A calmer Thursday':state.tab==='research'?'Research':'Memory',(state.tab==='memory'?'':btn('Sources','show-source','small'))+btn('Write','write','small'))}<div class="window-body">${sidebar()}<section class="window-content" aria-label="${state.tab}">${state.tab==='conversation'?conversation():state.tab==='research'?research():memory()}</section>${state.tab==='memory'?'':inspector()}</div></section>`;}
const settingRows = {
 General:[['Show Wisp','Global shortcut','key'],['Open on login','Start quietly in the menu bar','switch'],['Expand on hover','Keyboard access is always available','switch'],['Daily brief','A quiet start to the day','time']],
 Appearance:[['Appearance','Window surfaces follow your preference','appearance'],['Reading size','Conversation and report text','size'],['Reduce motion','Additional reduction; also follows macOS','motion'],['Opaque materials','Remove simulated transparency','opaque']],
 Connections:[['Mail','Connected · Work account','status'],['Calendar','Connected · Work calendar','status'],['Notes','Not connected in this fixture','status']],
 'Privacy & access':[['Action approval','Review outbound actions before execution','status'],['Saved memory','Review facts and their sources','memory'],['Activity history','Available in the production app','status']],
 Models:[['Chat model','Configured on this Mac','status'],['Research model','Uses your configured research role','status']]
};
function settingControl(kind,label){if(kind==='key')return '<span class="pill">⌥ Space</span>';if(kind==='switch')return `<input class="switch" type="checkbox" data-preference="${label}" ${state.preferences[label]?'checked':''} aria-label="${label}">`;if(kind==='time')return '<span class="pill">9:00 AM</span>';if(kind==='appearance')return `<select aria-label="Window appearance" data-setting="theme">${['system','light','dark'].map(x=>`<option value="${x}" ${state.theme===x?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select>`;if(kind==='size')return `<select aria-label="Reading size" data-setting="size"><option value="1" ${!state.readingLarge?'selected':''}>Default</option><option value="2" ${state.readingLarge?'selected':''}>200%</option></select>`;if(['motion','opaque'].includes(kind))return `<input class="switch" type="checkbox" data-setting="${kind}" aria-label="${label}" ${$('#'+kind).checked?'checked':''}>`;if(kind==='memory')return btn('Review','open-memory','secondary');return '<span class="small muted">Sample</span>';}
function settings(){return `<section class="window settings-window ${state.sidebar?'':'hidden-sidebar'}" aria-label="Wisp Settings window">${titlebar('Settings')}<div class="window-body"><nav class="sidebar" aria-label="Settings categories"><label class="search-field">${icon('search')}<input id="settings-search" placeholder="Search settings" aria-label="Search settings"></label><div style="height:12px"></div>${Object.keys(settingRows).map(c=>`<button data-category="${c}" aria-pressed="${state.category===c}">${icon(c==='General'?'settings':c==='Connections'?'research':c==='Privacy & access'?'memory':'sidebar')}${c}</button>`).join('')}<div class="sidebar-bottom small muted">Wisp · Design preview</div></nav><section class="window-content"><div class="content-inner"><span class="eyebrow">Make yourself at home</span><h1 id="settings-title">${state.category}</h1><p class="muted small">A few considered defaults. Your Mac, your rhythm.</p><div id="settings-rows">${settingsRows()}</div><p class="muted small">Preview controls change this prototype only.<br>Production preferences would save automatically.</p></div></section></div></section>`;}
function settingsRows(query=''){const groups=query?Object.entries(settingRows):[[state.category,settingRows[state.category]]];const matches=groups.flatMap(([cat,rows])=>rows.filter(r=>(cat+' '+r[0]+' '+r[1]).toLowerCase().includes(query.toLowerCase())).map(r=>({...r,category:cat})));return matches.length?`<div class="settings-group">${matches.map(r=>`<div class="setting-row"><div><b>${r[0]}</b><span class="small muted">${query?r.category+' · ':''}${r[1]}</span></div>${settingControl(r[2],r[0])}</div>`).join('')}</div>`:'<p class="muted" role="status">No settings match. Try “appearance” or “approval”.</p>';}
const results=[['Launch timeline','Launch planning · Section 1','The first release is planned for October. The team will review the scope next Thursday.'],['Thursday planning session','Launch planning · Section 2','Let’s review the launch timeline and keep the first release focused.'],['Release checklist','Launch planning · Section 3','Confirm the first-run experience, feedback channel, and support coverage.']];
function search(){return `<section class="notch search-panel" aria-label="Smart Search"><div class="search-field">${icon('search')}<label class="sr-only" for="query">Search the current document</label><input id="query" value="${esc(state.search)}" placeholder="Search this document">${btn('<span class="sr-only">Close search</span>','return-notch','icon','close')}</div><div class="search-scope"><span class="pill">${icon('file')} Launch planning · Sample document</span><span class="small muted">⌘⇧F</span></div><div id="search-matches">${searchMatches()}</div><div class="search-foot"><span>↑↓ Select &nbsp; · &nbsp; ↵ View passage</span><span>Esc to close</span></div></section>`;}
function searchMatches(){const matches=results.map((x,i)=>({x,i})).filter(({x})=>!state.search||x.join(' ').toLowerCase().includes(state.search.toLowerCase()));if(!matches.length)return '<div style="padding:35px 12px"><b>No matching passages</b><p class="muted">Try “launch” or “Thursday”. Your document scope is unchanged.</p></div>';if(!matches.some(r=>r.i===state.selection))state.selection=matches[0].i;return `<div class="eyebrow">Matching passages · ${matches.length}</div><div class="search-results">${matches.map(({x,i})=>`<button class="result" data-result="${i}" aria-pressed="${state.selection===i}"><span class="result-number">${i+1}</span><span><b>${x[0]}</b><p>${x[1]}</p><p>${x[2]}</p></span></button>`).join('')}</div><div class="search-answer" aria-label="Selected source passage"><span class="eyebrow">Selected passage · ${state.selection+1}</span><p>${results[state.selection][2]}</p><span class="muted small">${results[state.selection][1]} · Illustrative content</span></div>`;}
function variants(){let list=state.view==='notch'?[['idle','Idle'],['processing','Processing'],['approval','Approval']]:state.view==='workspace'?[['wide','1120 pt'],['narrow','720 pt'],['text','200% reading text']]:state.view==='settings'?[['General','General'],['Appearance','Appearance'],['Privacy & access','Privacy']]:[['launch timeline','Matches'],['zz-no-match','No results']];$('#variants').innerHTML=list.map(([val,label])=>`<button data-variant="${val}" aria-pressed="${val===(state.view==='notch'?state.notch:state.view==='workspace'?state.width:state.view==='settings'?state.category:state.search)}">${label}</button>`).join('');$('#variant-note').textContent=state.view==='workspace'?'Drag the lower-right corner to resize · Browser approximation':state.view==='notch'?'Camera safe area reserved · No controls in the hardware':state.view==='settings'?'Local preference simulation':'Source-scoped search · Synthetic content';}
function applyAppearance(){let theme=state.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):state.theme;$('#desktop').classList.toggle('light',theme==='light');$('#desktop').classList.toggle('dark',theme==='dark');$('#desktop').classList.toggle('plain',state.display==='plain');['motion','contrast','opaque'].forEach((x,i)=>$('#desktop').classList.toggle(['reduce-motion','high-contrast','opaque'][i],$('#'+x).checked));}
function render(){const active=document.activeElement;const focusId=active?.id;const focusData=active?.dataset?Object.entries(active.dataset).find(([k])=>['tab','category','variant','action'].includes(k)):null;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===state.view));variants();applyAppearance();$('#surface').innerHTML=state.view==='notch'?notch():state.view==='workspace'?workspace():state.view==='settings'?settings():search();$('#caption').textContent=(state.display==='plain'?'EXTERNAL DISPLAY':'NOTCHED MAC')+' · '+(state.view==='notch'?state.notch.toUpperCase():state.view.toUpperCase());const copy={notch:['A little presence.','The black silhouette stays fused to the hardware. A clearer hierarchy gives requests, progress, and decisions their own space.'],workspace:['Room to think.','A standard, resizable home for longer conversations. Evidence stays close, and Wisp’s quiet character carries through.'],settings:['Familiar, down to the details.','Searchable categories, readable form rows, and system-aware appearance bring the supporting surfaces together.'],search:['The right detail, in context.','A clear query, a visible document scope, and readable source passages. Retrieval mechanics stay out of the way.']};$('#idea-title').textContent=copy[state.view][0];$('#idea-description').textContent=copy[state.view][1];if(focusId)document.getElementById(focusId)?.focus();else if(focusData){const [key,value]=focusData;[...document.querySelectorAll('button')].find(b=>b.dataset[key]===value)?.focus();}}
function navigate(view){state.view=view;state.sidebar=true;state.showSources=false;render();const target=view==='notch'?($('#prompt')||$('.notch h1')):view==='search'?$('#query'):$('.window-content h1');if(target){if(target.tagName==='H1')target.tabIndex=-1;target.focus();}announce(view+' concept');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){navigate(b.dataset.view);return;}if(b.dataset.tab){state.tab=b.dataset.tab;render();return;}if(b.dataset.category){state.category=b.dataset.category;render();return;}if(b.dataset.result){state.selection=Number(b.dataset.result);$('#search-matches').innerHTML=searchMatches();return;}if(b.dataset.variant){const v=b.dataset.variant;if(state.view==='notch')state.notch=v;else if(state.view==='workspace'){if(v==='text'){state.readingLarge=!state.readingLarge;$('#desktop').classList.toggle('reading-large',state.readingLarge);}else state.width=v;}else if(state.view==='settings')state.category=v;else{state.search=v;state.selection=0;}render();return;}const a=b.dataset.action;if(!a)return;
 if(a==='open-window'){navigate('workspace');return;}if(a==='open-settings'){navigate('settings');return;}if(a==='open-search'){navigate('search');return;}if(a==='open-memory'){state.tab='memory';navigate('workspace');return;}if(a==='return-notch'){navigate('notch');return;}if(a==='sidebar'){state.sidebar=!state.sidebar;render();return;}if(a==='show-source'){state.showSources=true;state.hideSources=false;render();$('.inspector').setAttribute('tabindex','-1');$('.inspector').focus();return;}if(a==='hide-source'){state.showSources=false;state.hideSources=true;render();document.querySelector('[data-action="show-source"]')?.focus();return;}if(a==='write'){if(state.tab!=='conversation'){state.tab='conversation';render();}$('#prompt')?.focus();return;}if(a==='memory-done'){const row=b.closest('.memory-row');row.querySelector('p').contentEditable='false';b.textContent='Review';b.dataset.action='memory-0';announce('Sample memory updated in this view.');return;}if(a.startsWith('memory-')){const n=Number(a.split('-')[1]);const row=b.closest('.memory-row');row.querySelector('p').contentEditable='true';row.querySelector('p').setAttribute('aria-label','Edit sample memory');row.querySelector('p').focus();b.textContent='Done';b.dataset.action='memory-done';announce('Editing sample memory. Changes remain in this view only.');return;}
 if(a==='sample-day'){state.prompt='What’s ahead today?';state.tab='conversation';navigate('workspace');return;}if(a==='new'){state.prompt='';state.notch='idle';navigate('notch');return;}if(a==='review'||a==='resume'){state.notch='approval';navigate('notch');return;}if(a==='send'){state.prompt=$('#prompt')?.value||'Find Maya’s latest email and draft a reply for Thursday.';state.notch='processing';navigate('notch');announce('Preparing a sample reply. Use the Approval state control to inspect the next step.');return;}if(a==='stop')state.notch='canceled';if(a==='approve')state.notch='approved';if(a==='defer')state.notch='deferred';if(a==='hide')state.notch=state.notch==='approval'?'deferred':'hidden';if(a==='show')state.notch='idle';render();announce(a==='approve'?'Sample approval recorded. No email was sent.':a==='defer'?'Approval remains pending.':a==='stop'?'Request stopped.':'View updated.');});
document.addEventListener('input',e=>{if(e.target.id==='prompt')state.prompt=e.target.value;if(e.target.id==='draft')state.draft=e.target.value;if(e.target.id==='query'){state.search=e.target.value;$('#search-matches').innerHTML=searchMatches();}if(e.target.id==='settings-search'){$('#settings-title').textContent=e.target.value?'Search results':state.category;$('#settings-rows').innerHTML=settingsRows(e.target.value);}});
document.addEventListener('change',e=>{if(e.target.id==='theme'){state.theme=e.target.value;applyAppearance();}if(e.target.id==='display'){state.display=e.target.value;applyAppearance();}if(['motion','contrast','opaque'].includes(e.target.id))applyAppearance();const setting=e.target.dataset.setting;if(setting==='theme'){state.theme=e.target.value;$('#theme').value=state.theme;applyAppearance();}if(setting==='size'){state.readingLarge=e.target.value==='2';$('#desktop').classList.toggle('reading-large',state.readingLarge);}if(e.target.dataset.preference)state.preferences[e.target.dataset.preference]=e.target.checked;if(['motion','opaque'].includes(setting)){$('#'+setting).checked=e.target.checked;applyAppearance();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(state.view==='notch'){state.notch=state.notch==='approval'?'deferred':'hidden';render();}else navigate('notch');}if(e.key==='Enter'&&e.target.id==='prompt'&&!e.shiftKey&&!e.isComposing){e.preventDefault();document.querySelector('[data-action="send"]').click();}if(state.view==='search'&&(e.target.id==='query'||e.target.closest('[data-result]'))&&['ArrowDown','ArrowUp','Enter'].includes(e.key)){const rs=[...document.querySelectorAll('[data-result]')];if(rs.length){e.preventDefault();const i=rs.findIndex(r=>Number(r.dataset.result)===state.selection);state.selection=Number(rs[(i+(e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0)+rs.length)%rs.length].dataset.result);$('#search-matches').innerHTML=searchMatches();if(e.key==='Enter')document.querySelector(`[data-result="${state.selection}"]`).focus();}}});
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',applyAppearance);
const params=new URLSearchParams(location.search);if(['notch','workspace','settings','search'].includes(params.get('view')))state.view=params.get('view');if(['idle','processing','approval'].includes(params.get('state')))state.notch=params.get('state');if(['conversation','research','memory'].includes(params.get('tab')))state.tab=params.get('tab');if(['dark','light','system'].includes(params.get('theme')))state.theme=params.get('theme');if(params.get('display')==='plain')state.display='plain';if(params.get('width')==='narrow')state.width='narrow';if(params.get('category') in settingRows)state.category=params.get('category');$('#theme').value=state.theme;$('#display').value=state.display;render();
